<?php
require_once __DIR__.'/includes/functions.php';$user=require_login();require_permission($user,'emr.archive');$pageTitle='Pencarian dan Arsip Rekam Medis';$pdo=db();$search=trim($_GET['q']??'');$date=trim($_GET['birth_date']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!in_array($user['role_code'],['rekammedis','admin_simrs'],true)){http_response_code(403);exit('Hanya admin dan petugas rekam medis yang dapat mengunggah scan berkas.');}check_csrf();$reg=(int)($_POST['registration_id']??0);$desc=trim($_POST['description']??'');$file=$_FILES['attachment']??null;
 try{
  if(!$reg||!$desc||!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>10*1024*1024)throw new RuntimeException('Isi kunjungan, deskripsi dan berkas maksimal 10 MB.');
  $q=$pdo->prepare('SELECT id FROM registrations WHERE id=?');$q->execute([$reg]);if(!$q->fetchColumn())throw new RuntimeException('Kunjungan tidak ditemukan.');
  $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allow=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($allow[$mime]))throw new RuntimeException('Hanya PDF, JPG dan PNG yang diizinkan.');
  $folder=__DIR__.'/private_uploads';if(!is_dir($folder))mkdir($folder,0700,true);$name=bin2hex(random_bytes(20)).'.'.$allow[$mime];
  if(!move_uploaded_file($file['tmp_name'],$folder.'/'.$name))throw new RuntimeException('Berkas gagal disimpan.');
  $pdo->prepare('INSERT INTO emr_attachments(registration_id,description,stored_name,original_name,mime_type,uploaded_by) VALUES(?,?,?,?,?,?)')->execute([$reg,$desc,$name,basename($file['name']),$mime,$user['employee_id']]);flash('success','Lampiran rekam medis tersimpan.');
 }catch(Throwable $e){flash('error',$e->getMessage());}redirect('emr_archive.php');
}
$results=[];if($search!==''||$date!==''){
 $where=[];$params=[];
 if($search!==''){$where[]='(p.full_name LIKE ? OR p.medical_record_no LIKE ? OR r.registration_no LIKE ? OR p.nik LIKE ?)';$params=array_fill(0,4,'%'.$search.'%');}
 if($date!==''){$where[]='p.birth_date=?';$params[]=$date;}
 $q=$pdo->prepare('SELECT r.id,r.registration_no,r.visit_date,p.full_name,p.medical_record_no,p.birth_date,em.assessment,em.plan FROM registrations r JOIN patients p ON p.id=r.patient_id LEFT JOIN emr em ON em.registration_id=r.id WHERE '.implode(' AND ',$where).' ORDER BY r.id DESC LIMIT 100');$q->execute($params);$results=$q->fetchAll();
}
require __DIR__.'/includes/header.php';?>
<h1 class="page-title">Pencarian Arsip Rekam Medis</h1><p class="page-subtitle">Cari nomor registrasi, nomor rekam medis, NIK, nama pasien, atau tanggal lahir. Catatan klinis hanya dapat dibaca oleh petugas arsip.</p>
<div class="card"><h2 class="section-title">Pencarian Data Pasien</h2><form method="get" class="grid grid-3"><div class="field"><label>Nama / Nomor Registrasi / No. RM / NIK</label><input class="input" name="q" value="<?=e($search)?>" placeholder="Masukkan kata kunci"></div><div class="field"><label>Tanggal Lahir</label><input class="input" type="date" name="birth_date" value="<?=e($date)?>"></div><div class="field" style="align-self:end"><button class="btn btn-primary">Cari Rekam Medis</button></div></form></div>
<?php if($search!==''||$date!==''):?><div class="card" style="margin-top:18px"><h2 class="section-title">Hasil Pencarian (<?=count($results)?> kunjungan)</h2><div class="table-wrap"><table><thead><tr><th>Pasien</th><th>Registrasi</th><th>Asesmen / Rencana</th><th>Dokumen</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><b><?=e($r['full_name'])?></b><small><?=e($r['medical_record_no'].' · '.$r['birth_date'])?></small></td><td><?=e($r['registration_no'])?><small><?=e($r['visit_date'])?></small></td><td><b>Asesmen</b><small><?=e($r['assessment']?:'Belum tersedia')?></small><b>Rencana</b><small><?=e($r['plan']?:'Belum tersedia')?></small></td><td><?php $q=$pdo->prepare('SELECT id,description,original_name FROM emr_attachments WHERE registration_id=? ORDER BY id DESC');$q->execute([$r['id']]);foreach($q as $a):?><a href="emr_file.php?id=<?=$a['id']?>" target="_blank"><?=e($a['description'].' · '.$a['original_name'])?></a><br><?php endforeach;?></td></tr><?php endforeach;?><?php if(!$results):?><tr><td colspan="4">Tidak ada data yang cocok.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
<?php if(in_array($user['role_code'],['rekammedis','admin_simrs'],true)):?><div class="card" style="margin-top:18px"><h2 class="section-title">Unggah Dokumen Penunjang</h2><p class="note">Contoh: surat rujukan, hasil CT scan, berkas pemeriksaan yang dipindai. Unggah tidak mengubah isi catatan dokter.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Kunjungan Pasien</label><select class="input" name="registration_id" required><option value="">Pilih kunjungan</option><?php $q=$pdo->query('SELECT r.id,r.registration_no,p.full_name FROM registrations r JOIN patients p ON p.id=r.patient_id ORDER BY r.id DESC LIMIT 150');foreach($q as $row):?><option value="<?=$row['id']?>"><?=e($row['registration_no'].' · '.$row['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Keterangan Dokumen</label><input class="input" name="description" required></div><div class="field"><label>File (PDF, JPG, PNG; maksimal 10 MB)</label><input class="input" type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn btn-primary">Unggah Lampiran</button></form></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>
